print("Shift analysis:")
for r in [3,4,5,6,7]:
    input_set = set(demo3_input_cols[r])
    output_set = set(demo3_output_cols[r])

    # Find shift that maps input to output
    for shift in range(-10, 10):
        shifted = {c + shift for c in input_set} if shift > 0 else {c - (-shift) for c in input_set}
        if sorted(shifted) == sorted(output_set):
            print(f"Row {r}: shift = {shift}")
